test('Scan route uses one classification form instead of independent metadata/KKPR/PBT/PDF forms',()=>{const h=harness(),html=h.c.flowPage();assert.match(html,/scan-controller-slot/);assert.doesNotMatch(html,/service-tabs|flow-form|Detail KKPR|Detail PBT|Nama dari profil/);assert.ok(h.document.querySelector('#scan-form'));assert.equal(h.calls.length,0);assert.equal(h.media.calls,0);assert.equal(h.state.user.nomorIndukKependudukan,undefined);});
test('camera decode only fills raw input, retains live video identity and waits for explicit Buka hasil',async()=>{const h=harness(),video=h.document.querySelector('#scan-video');await h.click('scan-camera-start');assert.equal(video.hidden,false);assert.equal(h.calls.length,0);h.cameraCode(RAW);assert.equal(h.controller.snapshot().rawQ,RAW);assert.equal(h.document.querySelector('#scan-raw-q').value,RAW);assert.equal(h.document.querySelector('#scan-video'),video);assert.equal(video.hidden,true);assert.equal(video.srcObject,null);assert.equal(h.calls.length,0);assert.ok(h.media.stopped>0);await h.submit();assert.deepEqual(plain(h.calls[0].options.body),{operationId:CLASSIFY,values:{q:RAW},confirm:true});assert.equal(h.calls.length,3);});
test('manual typing stops camera and does not send any captured/edited code automatically',async()=>{const h=harness(),video=h.document.querySelector('#scan-video');await h.click('scan-camera-start');await h.input(' SYNTHETIC manually edited ');assert.equal(h.owner.camera.snapshot().stage,'idle');assert.equal(h.controller.snapshot().rawQ,' SYNTHETIC manually edited ');h.cameraCode('SYNTHETIC stale camera');assert.equal(h.controller.snapshot().rawQ,' SYNTHETIC manually edited ');assert.equal(h.document.querySelector('#scan-video'),video);assert.equal(h.calls.length,0);});
test('camera UI state changes never replace the controller textarea or video',async()=>{const h=harness(),input=await h.input(RAW),video=h.document.querySelector('#scan-video');input.focus();input.setSelectionRange(3,8);await h.click('scan-camera-start');assert.equal(h.document.querySelector('#scan-raw-q'),input);assert.equal(h.document.querySelector('#scan-video'),video);await h.click('scan-camera-stop');assert.equal(h.document.querySelector('#scan-raw-q'),input);assert.equal(h.document.activeElement,input);assert.deepEqual([input.selectionStart,input.selectionEnd],[3,8]);});
test('incremental controller paint preserves raw-input focus/caret without touching camera DOM',async()=>{const h=harness(),input=await h.input(RAW),video=h.document.querySelector('#scan-video');input.focus();input.setSelectionRange(4,12);h.c.scanPaint();const replacement=h.document.querySelector('#scan-raw-q');assert.notEqual(replacement,input);assert.equal(h.document.activeElement,replacement);assert.deepEqual([replacement.selectionStart,replacement.selectionEnd],[4,12]);assert.equal(replacement.value,RAW);assert.equal(h.document.querySelector('#scan-video'),video);});
