function pbtFixture(){return{status:200,data:{error:false,data:{nomor:'<SYNTHETIC-PBT>',kantor:'Kantor SINTETIS',daftarBidangTanah:[{nib:'A-DUP',lokasi:'Alamat <SINTETIS>',luas:'120',noBerkas:'',batas:{id:'A',geometri:{type:'MultiPolygon',coordinates:[[[[100,10],[102,12]],[],[[106,-6],[108,-8]]]]}}},{nib:'NULL',lokasi:'',luas:null,noBerkas:null,batas:null},{nib:'A-DUP-SECOND',lokasi:null,luas:'2',noBerkas:'3',batas:{id:'A',geometri:null}},{nib:'B',lokasi:null,luas:'4',noBerkas:'5',batas:{id:'B',geometri:{type:'MultiPolygon',coordinates:[[[[120,-10],[122,-12]]]]}}}]}}};}
function genericFixture(){return{status:200,data:{geometri:{type:'MultiPolygon',coordinates:[[[[106,-6],[106.001,-6],[106,-5.999],[106,-6]]]]},tipeHak:'SINTETIS'}};}
function installPbt(h,{pbt=pbtFixture(),geo=genericFixture()}={}){h.setApi(async(_,{body})=>{if(body.operationId===CLASSIFY)return classified();if(body.operationId===DOCUMENT)return{result:pdf()};if(body.operationId===META)return{result:{status:200,data:{error:true,data:{showRoute:1,type:'PetaBidangElektronik'}}}};if(body.operationId===PBT)return{result:await(typeof pbt==='function'?pbt():pbt)};if(body.operationId===GEO)return{result:await(typeof geo==='function'?geo():geo)};throw new Error('Outside synthetic host scope');});}
function cameraOf(node){return JSON.parse(decode(node.querySelector('template[data-official-camera]').textContent));}

test('PBT host starts special then generic reads without awaiting, shows generic foreground, and retains ready map nodes across independent completions',async()=>{
 const h=harness(),pbt=deferred(),geo=deferred();installPbt(h,{pbt:pbt.promise,geo:geo.promise});await h.input(RAW);await h.submit();const preview=h.controller.snapshot().outcome.pdf.previewUrl,work=h.click('scan-location');await tick();assert.deepEqual(h.calls.slice(3).map(call=>call.options.body.operationId),[PBT,GEO]);for(const call of h.calls.slice(3))assert.deepEqual(plain(call.options.body),{operationId:call.options.body.operationId,values:{q:RAW},scanContextId:CONTEXT});const frame=h.owner.location,genericPane=h.modal.querySelector('[data-scan-location-pane="generic"]'),pbtPane=h.modal.querySelector('[data-scan-location-pane="pbt"]');assert.equal(genericPane.hidden,false);assert.equal(pbtPane.hidden,true);assert.equal(h.controller.snapshot().locationBusy,true);geo.resolve(genericFixture());await tick();const map=genericPane.querySelector('[data-official-map]');assert.ok(map);map.camera={zoom:16,panned:true};pbt.resolve(pbtFixture());await tick();assert.equal(genericPane.querySelector('[data-official-map]'),map);assert.deepEqual(map.camera,{zoom:16,panned:true});assert.equal(genericPane.hidden,false);assert.equal(pbtPane.hidden,true);assert.ok(pbtPane.querySelector('[data-scan-pbt-panel]'));assert.equal(h.controller.snapshot().outcome.pdf.previewUrl,preview);assert.doesNotMatch(h.modal.innerHTML,/synthetic-scan-host-context|data-geojson/);h.modal.close();await work;assert.equal(h.owner.location,null);assert.equal(frame.disposed,true);assert.equal(h.modal.listeners.get('close').length,1);assert.equal(h.controller.snapshot().locationBusy,false);
});

test('PBT pane selection stays selected while generic background completes without repainting its camera or panel',async()=>{
 const h=harness(),geo=deferred();installPbt(h,{geo:geo.promise});await h.submit();const work=h.click('scan-location');await tick();await h.dispatch('click',h.modal.querySelector('[data-scan-location-kind="pbt"]'));const pane=h.modal.querySelector('[data-scan-location-pane="pbt"]'),map=pane.querySelector('[data-official-map]'),panel=pane.querySelector('[data-scan-pbt-panel]');assert.equal(pane.hidden,false);assert.equal(h.modal.querySelector('[data-scan-location-pane="generic"]').hidden,true);assert.deepEqual(cameraOf(map),{center:{lat:-7,lng:107},zoom:19,pin:true});geo.resolve(genericFixture());await tick();assert.equal(pane.hidden,false);assert.equal(pane.querySelector('[data-official-map]'),map);assert.equal(pane.querySelector('[data-scan-pbt-panel]'),panel);assert.equal(h.calls.length,5);h.modal.close();await work;
});

test('PBT search preserves caret, original count and source-ID first-match indices without replacing mounted maps or sending reads',async()=>{
 const h=harness();installPbt(h);await h.submit();const work=h.click('scan-location');await tick();await h.dispatch('click',h.modal.querySelector('[data-scan-location-kind="pbt"]'));const frame=h.owner.location,map=h.modal.querySelector('[data-scan-pbt-map]').firstElementChild,input=h.modal.querySelector('[data-scan-pbt-search]');input.value=' DUP ';input.focus();input.setSelectionRange(1,4);await h.dispatch('input',input);const replacement=h.modal.querySelector('[data-scan-pbt-search]');assert.notEqual(replacement,input);assert.equal(h.document.activeElement,replacement);assert.deepEqual([replacement.selectionStart,replacement.selectionEnd],[1,4]);assert.equal(replacement.value,' DUP ');assert.equal(frame.pbt.query,' DUP ');assert.equal(frame.pbt.details.rows.length,4);const buttons=h.modal.querySelector('[data-scan-pbt-panel]').querySelectorAll('[data-action="scan-pbt-select"]');assert.equal(buttons.length,2);assert.deepEqual(buttons.map(button=>button.dataset.sourceIndex),['0','0']);assert.equal(h.modal.querySelector('[data-scan-pbt-map]').firstElementChild,map);assert.equal(h.calls.length,5);assert.match(h.modal.innerHTML,/Alamat &lt;SINTETIS&gt;/);assert.match(h.modal.innerHTML,/Luas 120 m²/);assert.equal(h.modal.querySelector('script'),null);h.modal.close();await work;
});

