test('parallel current authentication failures clear the host once and remove modal listeners without stale duplicate expiry',async()=>{
 const h=harness(),pbt=deferred(),geo=deferred();installPbt(h,{pbt:pbt.promise,geo:geo.promise});await h.submit();const work=h.click('scan-location');await tick();const frame=h.owner.location;pbt.reject(Object.assign(new Error('SINTETIS actual expiry'),{code:'SESSION_EXPIRED'}));await work;assert.equal(h.state.authenticated,false);assert.equal(h.c.sessionEpoch,2);assert.equal(h.toasts.length,1);assert.equal(h.modal.open,false);assert.equal(frame.disposed,true);assert.equal(h.modal.listeners.get('close').length,1);geo.reject(Object.assign(new Error('SINTETIS duplicate expiry'),{code:'SESSION_EXPIRED'}));await tick();assert.equal(h.c.sessionEpoch,2);assert.equal(h.toasts.length,1);
});


