test('KKPR leading empty izin ring does not reserve an index; the later valid ring becomes dense0 and initial camera',async()=>{
 const h=harness(),response=kkprFixture();response.data.data.geometryData.features[2].geometry.coordinates=[[]];installKkpr(h,{kkpr:response});await h.submit();const work=h.click('scan-location');await tick();const frame=h.owner.location,panel=h.modal.querySelector('[data-scan-kkpr-panel]');assert.deepEqual(plain(frame.kkpr.model.entries.map(entry=>[entry.index,entry.sourceIndex])),[[0,4]]);assert.deepEqual(cameraOf(h.modal.querySelector('[data-scan-kkpr-map]')),{center:{lat:-11,lng:121},zoom:19,pin:true});assert.match(panel.innerHTML,/1 Bidang/);assert.equal(panel.querySelector('[data-kkpr-index="1"]'),null);assert.equal(h.calls.length,4);h.modal.close();await work;
});

for(const failAt of ['first','later'])test(`KKPR malformed ${failAt} active ring keeps typed source and only native-progressive dense entries with explicit warning`,async()=>{
 const h=harness(),response=kkprFixture(),source=failAt==='first'?2:4;response.data.data.geometryData.features[source].geometry.coordinates[0][0][0]='MALFORMED ACTIVE LEAF';installKkpr(h,{kkpr:response});await h.submit();const work=h.click('scan-location');await tick();const frame=h.owner.location,pane=h.modal.querySelector('[data-scan-location-pane="kkpr"]'),panel=pane.querySelector('[data-scan-kkpr-panel]'),wrapper=pane.querySelector('[data-scan-kkpr-map]');assert.equal(frame.kkpr.details.features.length,5);assert.equal(frame.kkpr.details.data.textualData.kkpr.nomor,'SYNTHETIC PRIVATE TEXTUAL NUMBER');assert.equal(frame.kkpr.model.partial,true);assert.equal(frame.kkpr.model.entries.length,failAt==='first'?0:1);assert.equal(panel.querySelectorAll('[data-action="scan-kkpr-select"]').length,failAt==='first'?0:1);assert.ok(pane.querySelector('.notice.warning'));assert.deepEqual(cameraOf(wrapper),failAt==='first'?{center:{lat:-6.2,lng:106.816666},zoom:19,pin:false}:{center:{lat:-7,lng:107},zoom:19,pin:true});assert.equal(wrapper.dataset.selectedPin,failAt==='first'?'false':'true');assert.match(h.main.innerHTML,/Lihat PDF/);assert.equal(h.state.authenticated,true);assert.equal(h.calls.length,4);h.modal.close();await work;
});

test('KKPR ready pane updates preserve manually panned map DOM; disconnected or invalid row commands cannot select or read',async()=>{
 const h=harness();installKkpr(h);await h.submit();const work=h.click('scan-location');await tick();const frame=h.owner.location,wrapper=h.modal.querySelector('[data-scan-kkpr-map]'),map=wrapper.firstElementChild,button=h.modal.querySelector('[data-kkpr-index="0"]');map.actualCamera={zoom:16,panned:true};frame.controller.select('kkpr');assert.equal(wrapper.firstElementChild,map);assert.deepEqual(map.actualCamera,{zoom:16,panned:true});const forged=h.document.createElement('button');forged.setAttribute('data-action','scan-kkpr-select');forged.setAttribute('data-kkpr-index','901');frame.slot.appendChild(forged);await h.dispatch('click',forged);assert.equal(frame.kkpr.selected,0);assert.equal(wrapper.firstElementChild,map);h.modal.close();await work;await h.dispatch('click',button);assert.equal(h.calls.length,4);assert.equal(h.toasts.length,0);
});
